CREATE TABLE games (id INTEGER PRIMARY KEY, name TEXT NOT NULL, original_name TEXT, year INTEGER, min_players INTEGER, max_players INTEGER, play_time INTEGER, weight REAL, image_url TEXT);
CREATE TABLE collection_items (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), bgg_id INTEGER NOT NULL REFERENCES games(id), source_coll_id TEXT, own INTEGER NOT NULL DEFAULT 0, for_trade INTEGER NOT NULL DEFAULT 0, wishlist INTEGER NOT NULL DEFAULT 0, wishlist_priority INTEGER, rating REAL, imported_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,bgg_id,source_coll_id));
CREATE TABLE copies (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), collection_item_id TEXT NOT NULL REFERENCES collection_items(id), cost_minor INTEGER, currency TEXT, acquisition_date TEXT, acquired_from TEXT, condition_text TEXT, private_comment TEXT, inventory_location TEXT, version_name TEXT, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX copies_owner_cost ON copies(user_id,active,cost_minor);
CREATE TABLE import_runs (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), row_count INTEGER NOT NULL, warning_count INTEGER NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE removal_reviews (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), copy_id TEXT NOT NULL REFERENCES copies(id), import_run_id TEXT NOT NULL REFERENCES import_runs(id), status TEXT NOT NULL DEFAULT 'pending', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE trades (id TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id), shipping_minor INTEGER NOT NULL DEFAULT 0, cash_minor INTEGER NOT NULL DEFAULT 0, currency TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, reversed_at TEXT);
CREATE TABLE trade_lines (id TEXT PRIMARY KEY, trade_id TEXT NOT NULL REFERENCES trades(id), copy_id TEXT REFERENCES copies(id), direction TEXT NOT NULL CHECK(direction IN('out','in')), title TEXT NOT NULL, carried_cost_minor INTEGER, allocated_cost_minor INTEGER);
CREATE TABLE invitations (id TEXT PRIMARY KEY, email TEXT NOT NULL COLLATE NOCASE, invited_by TEXT NOT NULL REFERENCES users(id), status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN('pending','accepted','revoked')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, accepted_at TEXT);
ALTER TABLE users ADD COLUMN disabled_at TEXT;
